<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import type { Product } from '../types'
import { api, currency } from '../services/api'
import { useAuthStore } from '../stores/auth'
import { useCartStore } from '../stores/cart'
import LoadingState from '../components/LoadingState.vue'
const route=useRoute();const router=useRouter();const auth=useAuthStore();const cart=useCartStore();const product=ref<Product|null>(null);const loading=ref(true);const error=ref('');const selected=ref('');const quantity=ref(1);const message=ref('');const busy=ref(false)
const variant=computed(()=>product.value?.variants.find(v=>v.id===selected.value)??product.value?.variants.find(v=>v.is_active&&v.stock_available>0)??product.value?.variants[0])
async function load(){loading.value=true;error.value='';try{product.value=await api.get<Product>(`/api/v1/products/${route.params.slug}`);selected.value=product.value.variants.find(v=>v.stock_available>0)?.id??product.value.variants[0]?.id??''}catch(e){error.value=e instanceof Error?e.message:'Produk tidak tersedia'}finally{loading.value=false}}
async function addCart(){if(!product.value||!variant.value)return;if(!auth.isAuthenticated){router.push({name:'login',query:{redirect:route.fullPath}});return};busy.value=true;message.value='';try{await cart.add(variant.value.id,quantity.value);message.value='Produk ditambahkan ke keranjang'}catch(e){message.value=e instanceof Error?e.message:'Gagal menambahkan'}finally{busy.value=false}}
async function wish(){if(!auth.isAuthenticated){router.push({name:'login'});return}if(!variant.value)return;try{await api.post(`/api/v1/wishlist/${variant.value.id}`);message.value='Ditambahkan ke wishlist'}catch(e){message.value=e instanceof Error?e.message:'Gagal menyimpan'}}
async function submitReview(event: SubmitEvent){event.preventDefault();if(!product.value)return;const form=event.target as HTMLFormElement;const data=new FormData(form);try{await api.post(`/api/v1/products/${product.value.id}/reviews`,{rating:Number(data.get('rating')),comment:String(data.get('comment')??'')});await load();message.value='Ulasan berhasil dikirim';form.reset()}catch(e){message.value=e instanceof Error?e.message:'Gagal mengirim ulasan'}}
onMounted(load);watch(()=>route.params.slug,load)
</script>
<template><LoadingState v-if="loading"/><div v-else-if="error" class="error-page"><h2>Produk tidak tersedia</h2><p>{{ error }}</p><RouterLink to="/products" class="button-primary">Kembali ke katalog</RouterLink></div><template v-else-if="product"><div class="breadcrumbs"><RouterLink to="/">Beranda</RouterLink> / <RouterLink to="/products">Katalog</RouterLink> / {{ product.name }}</div><section class="product-detail"><div class="detail-image"><img :src="product.image_url" :alt="product.name"/></div><div class="detail-info"><span class="category-pill">{{ product.category_name }}</span><h1>{{ product.name }}</h1><div class="product-rating large-rating"><span>★ {{ product.average_rating.toFixed(1) }}</span><span class="muted">{{ product.review_count }} ulasan</span></div><div class="detail-price">{{ currency(variant?.price??product.min_price) }}</div><p class="detail-description">{{ product.description }}</p><div class="stock-status" :class="variant?.stock_available?'in-stock':'out-stock'">● {{ variant?.stock_available?`Stok tersedia: ${variant.stock_available}`:'Stok habis' }}</div><label v-if="product.variants.length>1" class="field-label">Varian<select v-model="selected"><option v-for="v in product.variants" :key="v.id" :value="v.id">{{ Object.values(v.attributes).join(' / ') || v.sku }} — {{ currency(v.price) }} (stok {{ v.stock_available }})</option></select></label><div class="quantity-row"><span>Jumlah</span><div class="quantity-control"><button :disabled="quantity<=1" @click="quantity--">−</button><span>{{ quantity }}</span><button :disabled="!variant || quantity>=Math.min(99,variant.stock_available)" @click="quantity++">+</button></div></div><div class="detail-actions"><button class="button-primary" :disabled="busy||!variant||variant.stock_available<1" @click="addCart">{{ busy?'Menambahkan…':'Tambah ke keranjang' }}</button><button class="button-secondary" @click="wish">♡ Wishlist</button></div><p v-if="message" class="inline-message">{{ message }}</p><div class="detail-assurances"><span>✓ Checkout tervalidasi server</span><span>✓ Riwayat order tersimpan</span><span>✓ Bantuan pelanggan</span></div></div></section><section class="section review-section"><div class="section-heading"><div><p class="eyebrow">PENGALAMAN PELANGGAN</p><h2>Ulasan produk</h2></div></div><form v-if="auth.isAuthenticated" class="review-form" @submit="submitReview"><label>Rating<select name="rating"><option value="5">5 — Sangat baik</option><option value="4">4 — Baik</option><option value="3">3 — Cukup</option><option value="2">2 — Kurang</option><option value="1">1 — Buruk</option></select></label><label>Komentar<textarea name="comment" rows="3" placeholder="Ceritakan pengalamanmu setelah membeli…"></textarea></label><button class="button-secondary">Kirim ulasan</button><p class="muted small">Hanya pelanggan dengan pembelian terbayar yang dapat memberi ulasan.</p></form><div v-if="product.reviews?.length" class="review-list"><article v-for="r in product.reviews" :key="r.id" class="review-card"><strong>{{ r.customer_name ?? 'Customer' }}</strong><span class="review-stars">{{ '★'.repeat(r.rating) }}{{ '☆'.repeat(5-r.rating) }}</span><p>{{ r.comment || 'Tidak ada komentar.' }}</p></article></div><div v-else class="muted">Belum ada ulasan untuk produk ini.</div></section></template></template>
